# owner: platform
"""Seating charts: students sorted by name, row by row."""

from typing import List


def _label(student) -> str:
    return f"{student.last_name}, {student.first_name}"


def _sort_key(student) -> tuple:
    return (student.last_name, student.first_name)


def _check(students, seats: int) -> None:
    if seats <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")


def _chunks(names: List[str], seats: int) -> List[list]:
    return [
        names[start:start + seats]
        for start in range(0, len(names), seats)
    ]


def seating_rows(students, seats: int) -> List[str]:
    """One text line per row, sorted by last name."""
    _check(students, seats)
    ordered = sorted(students, key=_sort_key)
    rows = _chunks([_label(one) for one in ordered], seats)
    return [
        f"Row {numb}: " + " | ".join(row)
        for numb, row in enumerate(rows, 1)
    ]

