# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

PUPILS = [
    Student("a1", "Halloway", "Juno", "A"),
    Student("a2", "Dunmere", "Piet", "A"),
    Student("a3", "Adler", "Sam", "A")
]


class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        found = seating_rows(PUPILS, 2)
        self.assertEqual(found, [
            "Row 1: Adler, Sam | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    def test_bad_seat_counts_raise(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows(PUPILS, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
